-- Prices
UPDATE products p JOIN categories c ON c.id = p.category_id SET p.base_price = 2999.00 WHERE c.slug IN ('men', 'women');
UPDATE products p JOIN categories c ON c.id = p.category_id SET p.base_price = 1199.00 WHERE c.slug = 'kids';
UPDATE products SET base_price = 900.00 WHERE slug = 'predict-the-future-oversized-tee';
-- Drop any sale price that is no longer below the new price.
UPDATE products SET sale_price = NULL WHERE sale_price IS NOT NULL AND sale_price >= base_price;

